     "tipo": "localizar"
    },
    {
     "faz": "Ache a marca de mudança",
     "conta": "\"muita coisa mudou\"; \"cresceu\"",
     "porque": "Há avanços: do alistamento de Celina Guimarães (1927) e da posse da prefeita Alzira Soriano (1929) ao crescimento do percentual feminino no Congresso.",
     "tipo": "localizar"
    },
    {
     "faz": "Ache a marca de insuficiência",
